import{_ as t,o as r,c as o,ap as i}from"./chunks/framework.CuFS6FqL.js";const u=JSON.parse('{"title":"👩‍💻 Secure Coding Policy","description":"Secure coding requirements and OWASP checklist baseline for Syslifters projects.","frontmatter":{"title":"👩‍💻 Secure Coding Policy","description":"Secure coding requirements and OWASP checklist baseline for Syslifters projects."},"headers":[],"relativePath":"organization/secure-coding.md","filePath":"organization/secure-coding.md"}'),n={name:"organization/secure-coding.md"};function a(s,e,c,l,d,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/secure-coding.md for this page in Markdown format</div><h1 id="👩‍💻-secure-coding-policy" tabindex="-1">👩‍💻 Secure Coding Policy <a class="header-anchor" href="#👩‍💻-secure-coding-policy" aria-label="Permalink to &quot;👩‍💻 Secure Coding Policy&quot;">​</a></h1><p>We use the <a href="https://owasp.org/www-project-secure-coding-practices-quick-reference-guide/stable-en/02-checklist/05-checklist" target="_blank" rel="noreferrer">OWASP Secure Coding Practices Checklist</a> as the baseline, then apply a risk-based approach and improve continuously.</p><p>See also <a href="/organization/information-security-policy">Information Security Policy</a> and <a href="/organization/incident-response">incident response</a>.</p><p>Applies to anyone committing to <a href="https://docs.sysreptor.com/" target="_blank" rel="noreferrer">SysReptor</a>, <a href="https://sysreptor.com/" target="_blank" rel="noreferrer">SysReptor Portal</a>, <a href="https://docs.sysreptor.com/cli/getting-started/" target="_blank" rel="noreferrer">reptor</a>, or <a href="https://sysleaks.com/" target="_blank" rel="noreferrer">SysLeaks</a>.</p><p>Additionally, the following requirements must be met:</p><ul><li>Every API endpoint has automated authorization tests. In Django projects that means covering it in <code>test_api.py</code>, gating with <code>permission_classes</code> in <code>views.py</code>, and adding explicit tests when class-level permissions are not enough.</li><li>If users with the same permission level can use one endpoint but only with a limited dataset (e.g., list their own projects, not those of others), cover that with explicit tests. In Django projects that means <code>get_queryset</code> in <code>views.py</code>, preferably using <code>only_permitted</code> (in <code>queryset.py</code>).</li><li>Do not commit secrets. Tokens, keys, and connection strings stay out of git.</li><li>Do not ship dependencies with known exploitable vulnerabilities. Patch or replace on a risk basis.</li></ul><h2 id="further-conventions" tabindex="-1">Further conventions <a class="header-anchor" href="#further-conventions" aria-label="Permalink to &quot;Further conventions&quot;">​</a></h2><ul><li>We use <a href="https://open-vsx.org/extension/charliermarsh/ruff" target="_blank" rel="noreferrer">ruff</a> for linting and formatting</li></ul><p>Last reviewed: 03/09/2026</p>',10)])])}const g=t(n,[["render",a]]);export{u as __pageData,g as default};
